<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { operationJSON, checkedOperation } from '../api/operations'
import KeySecurityPanel from './KeySecurityPanel.vue'
const props = defineProps<{ ids: string[] }>()
const open = ref(false), text = ref('206.82.2.46'), version = ref(0), replace = ref(false), error = ref(''), busy = ref(false)
async function load() { try {const v = await operationJSON<{allowedIPs: string[];version: number}>('/channel-monitor/key-policy');text.value = v.allowedIPs.join('\n');version.value = v.version} catch (e: any) {error.value=e.message} }
onMounted(load)
async function show() { open.value=!open.value;if(open.value)await load() }
async function save(apply: boolean) { busy.value=true;error.value='';try {const v=await operationJSON<{version:number}>('/channel-monitor/key-policy',{method:'PUT',body:JSON.stringify({allowedIPs:text.value.split(/[\s,]+/).filter(Boolean),version:version.value})});version.value=v.version;if (apply) await checkedOperation({kind:'whitelist',ids:props.ids,replace:replace.value});window.dispatchEvent(new Event('transithub:key-policy'))} catch(e: any){error.value=e.message}finally{busy.value=false} }
</script>
<template><div class="flex flex-wrap items-center gap-2 text-sm"><KeySecurityPanel /><button type="button" class="rounded-lg border border-border/50 bg-surface px-3 py-1.5 text-xs" @click="show">Key IP：<span class="font-mono">{{text.split(/[\s,]+/).filter(Boolean).join(', ')}}</span> · 设置</button><Teleport to="body"><div v-if="open" class="fixed inset-0 z-[80] flex items-center justify-center bg-black/40 p-4" @click.self="!busy&&(open=false)"><section role="dialog" aria-modal="true" aria-label="统一 Key 白名单" class="w-full max-w-lg space-y-3 rounded-xl border border-border/50 bg-surface p-5 shadow-xl"><div class="flex justify-between"><h3 class="font-semibold">统一 Key IP 白名单</h3><button :disabled="busy" aria-label="关闭统一白名单" @click="open=false">✕</button></div><p>新建对接与预检 Key 自动使用以下白名单；已有 Key 可批量同步，独立分组策略优先。</p><textarea v-model="text" rows="3" class="w-full rounded border border-border/50 bg-background p-2" aria-label="允许的 IP 和 CIDR" /><label class="flex gap-2"><input v-model="replace" type="checkbox" />整体覆盖已有地址（默认保留自定义地址，仅替换 TransitHub 管理的地址）</label><p v-if="error" class="text-red-500">{{ error }}</p><div class="flex gap-3"><button type="button" :disabled="busy" class="text-primary" @click="save(false)">保存默认策略</button><button type="button" :disabled="busy || !ids.length" class="text-primary" @click="save(true)">保存并同步 {{ ids.length }} 个目标</button></div></section></div></Teleport></div></template>
